<?php namespace App\Console\Commands;use Illuminate\Console\Command;use App\Models\{Order,VendorCommission};class CalculateVendorCommissions extends Command{protected $signature='shoply:vendor-commissions';protected $description='Calculate vendor commissions for delivered orders.';public function handle(){Order::with('items')->where('status','delivered')->where('payment_status','paid')->chunkById(100,function($orders){foreach($orders as $o){foreach($o->items->whereNotNull('vendor_id') as $i){if(VendorCommission::where('order_id',$o->id)->where('vendor_id',$i->vendor_id)->exists())continue;$gross=$i->line_total;$vendor=$i->vendor; if(!$vendor)continue;$commission=round($gross*((float)$vendor->commission_rate/100),2);VendorCommission::create(['vendor_id'=>$vendor->id,'order_id'=>$o->id,'gross'=>$gross,'commission'=>$commission,'net'=>$gross-$commission]);$vendor->increment('balance',$gross-$commission);}}});$this->info('Vendor commissions calculated.');return self::SUCCESS;}}
